<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {api,APIError} from '../api';
import type {SystemDesign} from '../systemTypes';
import {inputKey,executionInputs,type Preparation,type ExecutionEvidence,type ExecutionInput} from '../executionTypes';
import {useWorkspaceDraft} from '../composables/useWorkspaceDraft';
import {useActionFeedback} from '../composables/useNotifications';
import DraftStatus from './DraftStatus.vue';
import SystemScenarioEditor from './SystemScenarioEditor.vue';
import SystemWorkflowTrace from './SystemWorkflowTrace.vue';
import SystemReplayPanel from './SystemReplayPanel.vue';
const props=defineProps<{design:SystemDesign}>();
const formKey=(p:ExecutionInput)=>JSON.stringify([props.design.id,inputKey(p)]);
const emit=defineEmits<{locate:[path:string]}>();
const preparation=ref<Preparation|null>(null),preparedDesign=ref(''),evidence=ref<ExecutionEvidence|null>(null);
const values=ref<Record<string,any>>({});
const recovery=useWorkspaceDraft('system-execution-inputs',{values});
const busy=ref(''),error=ref(''),notice=ref(''),step=ref(0);
const issues=ref<{path:string;message:string}[]>([]);
const focusedStep=computed(()=>{const event=evidence.value?.report.events[step.value];return event?.scenarioStep?evidence.value?.scenario?.steps[event.scenarioStep-1]:undefined;});
const orderedTasks=computed(()=>{const plan=evidence.value?.plan;if(!plan)return [];if(focusedStep.value?.workflow)return [];const message=evidence.value?.report.events[step.value]?.message;if(message){const event=evidence.value?.report.events[step.value];return [...new Set([event?.taskId,event?.target].filter(Boolean))].map(id=>plan.tasks.find(t=>t.id===id)!).filter(Boolean);}const target=focusedStep.value?.kind!=='invoke'?focusedStep.value?.taskId:undefined;return (target?[target]:plan.order).map(id=>plan.tasks.find(t=>t.id===id)!).filter(Boolean);});
const visibleLinks=computed(()=>focusedStep.value&&focusedStep.value.kind!=='invoke'?[]:evidence.value?.plan.links||[]);
const history=ref<{id:string;createdAt:string;name:string;taskCount:number}[]>([]);
useActionFeedback('System execution',busy,notice,error);
const stamp=computed(()=>JSON.stringify(props.design));
const ready=computed(()=>preparation.value&&preparedDesign.value===stamp.value);
const current=computed(()=>evidence.value?.report.events[step.value]);
const stale=computed(()=>evidence.value&&JSON.stringify(evidence.value.design)!==stamp.value);
const tasks=computed(()=>evidence.value?.plan.tasks||preparation.value?.plan.tasks||[]);
const journeyKinds=['intent_created','dispatched','delivered','recipient_committed','acknowledged'];
const messageJourney=computed(()=>{const event=current.value;if(!event?.message)return [];return journeyKinds.map(kind=>({kind,label:kind.replaceAll('_',' '),observed:evidence.value!.report.events.slice(0,step.value+1).some(e=>e.kind===kind&&(kind==='intent_created'?!!e.intentIds?.includes(event.message?.messages.find(m=>m.id===event.message?.step.messageId)?.sourceIntentId||''):e.message?.channelId===event.message?.channelId&&e.message?.step.messageId===event.message?.step.messageId))}));});
const activeTask=computed(()=>(current.value?.kind==='transfer'||['delivered','recipient_committed','recipient_replayed','acknowledged','acknowledgement_lost'].includes(current.value?.kind||''))?current.value?.target:current.value?.taskId);
const name=(id:string)=>tasks.value.find(t=>t.id===id)?.name||id;
watch(()=>props.design.id,()=>{history.value=[];});
async function action(label:string,fn:()=>Promise<void>){if(busy.value)return;busy.value=label;error.value='';notice.value='';issues.value=[];try{await recovery.ready;await fn();}catch(e){error.value=(e as Error).message;if(e instanceof APIError)issues.value=e.issues;}finally{busy.value='';}}
async function prepare(){await action('Preparing model execution',async()=>{
 const snapshot=stamp.value;const p=await api<Preparation>('/systems/execution/prepare','POST',{design:JSON.parse(snapshot)});
 if(stamp.value!==snapshot){notice.value='Design changed; prepare again';return;}
 preparation.value=p;preparedDesign.value=snapshot;evidence.value=null;
 for(const port of p.plan.inputs){const key=formKey(port);if(port.type==='record'){const previous=values.value[key];values.value[key]=Object.fromEntries((port.fields||[]).map(f=>[f.name,previous&&typeof previous==='object'&&!Array.isArray(previous)?previous[f.name]??'':'']));}else if(values.value[key]===undefined||typeof values.value[key]==='object')values.value[key]=port.type==='collection'?'[]':'';}
 notice.value='Plan prepared. Supply every external input; linked inputs are routed automatically.';
 });}
async function run(){if(!ready.value||!preparation.value)return;await action('Executing component graph',async()=>{
 const inputs=executionInputs(preparation.value!.plan.inputs,Object.fromEntries(preparation.value!.plan.inputs.map(p=>[inputKey(p),values.value[formKey(p)]])));
 const result=await api<ExecutionEvidence>('/systems/execution/run','POST',{design:JSON.parse(preparedDesign.value),inputs});
 evidence.value=result;step.value=0;notice.value='Model execution saved. Step through the token trace.';
 });}
function sample(){if(!preparation.value)return;for(const p of preparation.value.plan.inputs){if(p.type==='record'&&p.fields?.length===2&&p.fields.every(f=>f.type==='string'&&['encounterId','patientId'].includes(f.name)))values.value[formKey(p)]={encounterId:'synthetic-encounter-001',patientId:'synthetic-patient-001'};if(p.type==='record'&&p.fields?.length===3&&p.fields.every(f=>['tenantId','resourceId','quantity'].includes(f.name)))values.value[formKey(p)]={tenantId:'tenantDefault',resourceId:'resourceDefault',quantity:2};}notice.value='Synthetic values filled for matching example inputs';}
async function loadHistory(){await action('Loading execution history',async()=>{const id=props.design.id;const rows=await api<typeof history.value>('/systems/executions?systemId='+encodeURIComponent(id));if(props.design.id===id)history.value=rows;});}
async function load(id:string){await action('Opening saved execution',async()=>{evidence.value=await api<ExecutionEvidence>('/systems/executions/'+encodeURIComponent(id));step.value=0;});}
function focusOwner(id:string){const index=evidence.value?.report.events.findIndex(e=>e.scenarioStep===current.value?.scenarioStep&&(e.taskId===id||(e.message&&e.target===id))&&(e.kind==='started'||e.kind==='restarted'||e.message));if(index!==undefined&&index>=0)step.value=index;}
function download(){if(!evidence.value)return;const url=URL.createObjectURL(new Blob([JSON.stringify(evidence.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='system-execution.json';a.click();URL.revokeObjectURL(url);}
</script>
<template>
<section class="execution-panel" :inert="recovery.status.value==='loading'" :aria-busy="!!busy">
 <h2>Execute connected components</h2><p class="scope">A deterministic offline run combines typed dataflow, shared state owners, workflow tokens and broker acknowledgements. Workflow branches and loops follow explicit responses and signals; dataflow arrows remain acyclic. Each run starts fresh. No external I/O, resource timing or claim evaluation.</p>
 <div class="actions"><button :disabled="!!busy" @click="prepare">Prepare execution</button><button :disabled="!!busy||!ready||(!!preparation?.plan.channels?.length||!!preparation?.plan.workflows?.length)" @click="run">Run model</button><button :disabled="!!busy" @click="loadHistory">Saved executions</button><DraftStatus :draft="recovery"/><span role="status">{{busy}}</span></div>
 <div v-if="error" role="alert" class="error"><p>{{error}}</p><p v-for="issue in issues" :key="issue.path+issue.message">{{issue.path}}: {{issue.message}} <button v-if="issue.path.startsWith('components')||issue.path.startsWith('connections')||issue.path.startsWith('deploymentPlans')||issue.path.startsWith('executionProviders')" @click="emit('locate',issue.path)">Locate in design</button></p></div>
 <p v-if="preparation&&!ready" class="scope">The design changed. Prepare again before running.</p>
 <div v-if="history.length" class="history"><button v-for="item in history" :key="item.id" :disabled="!!busy" @click="load(item.id)">{{new Date(item.createdAt).toLocaleString()}} · {{item.name}} · {{item.taskCount}} tasks</button></div>
 <section v-if="ready&&preparation" class="input-form"><details v-if="preparation.providerChecks?.length"><summary>Provider compatibility · {{preparation.providerChecks.length}} bindings checked</summary><article v-for="c in preparation.providerChecks" :key="c.componentId+c.requirement"><strong>{{c.satisfied?'✓':'✗'}} {{c.componentId}} / {{c.requirement}} → {{c.providerId}}</strong><p>Required: {{c.required.join(', ')}}</p><p>Provided: {{c.provided.join(', ')}}</p></article></details><p v-for="task in preparation.plan.tasks.filter(t=>t.state)" :key="task.id" class="scope">{{task.name}} · {{task.state?.provider.id}} · {{task.state?.provider.kind}}@{{task.state?.provider.version}}. Graph entry: {{task.state?.entryCommand||task.state?.machine.machine.commands[0]?.name}}. Fresh owned state per run; one entry invocation.</p><p v-if="preparation.plan.channels?.length||preparation.plan.workflows?.length" class="scope">This design has message channels or workflows. Use a shared scenario below to order owner calls, workflow events, dispatch, delivery, retries and restarts.</p><details v-if="!preparation.plan.channels?.length&&!preparation.plan.workflows?.length"><summary>External inputs for a single graph invocation</summary><h3>External inputs</h3><p>Only inputs without a producer are shown. Fields are required.</p><button @click="sample">Use example inputs</button>
  <p v-if="!preparation.plan.inputs.length">This plan has no external inputs.</p>
  <fieldset v-for="port in preparation.plan.inputs" :key="inputKey(port)" :class="{invalid:issues.some(i=>i.path.includes(port.taskId)&&i.path.includes(port.name))}"><legend>{{preparation.plan.tasks.find(t=>t.id===port.taskId)?.name}} / {{port.name}} · {{port.type}}</legend>
   <small v-if="port.recordRef">{{port.recordRef.contractId}}@{{port.recordRef.version}} · {{port.recordRef.record}}</small>
   <template v-if="port.type==='record'"><label v-for="field in port.fields" :key="field.name">{{field.name}} *<select v-if="field.type==='boolean'" v-model="values[formKey(port)][field.name]"><option value="">Choose…</option><option value="true">true</option><option value="false">false</option></select><input v-else v-model="values[formKey(port)][field.name]" :type="field.type==='integer'?'number':'text'"/></label></template>
   <label v-else-if="port.type==='collection'">JSON array of records *<textarea v-model="values[formKey(port)]" rows="4"/></label>
   <label v-else>{{port.name}} *<select v-if="port.type==='boolean'" v-model="values[formKey(port)]"><option value="">Choose…</option><option value="true">true</option><option value="false">false</option></select><input v-else v-model="values[formKey(port)]" :type="port.type==='integer'?'number':'text'"/></label>
  </fieldset></details>
 </section>
 <SystemScenarioEditor v-if="ready&&preparation&&(preparation.plan.tasks.some(t=>t.state)||preparation.plan.workflows?.length)" :key="design.id" :plan="preparation.plan" :design="design" @result="result=>{evidence=result;step=0}"/>
 <section v-if="evidence" class="trace-view"><h3>Token trace · {{evidence.report.mode}}</h3><p>The trace uses saved inputs. Editing the form affects only the next run.</p><p v-if="stale" class="scope">Saved evidence belongs to a different design snapshot. The trace below uses that snapshot.</p>
  <SystemReplayPanel :evidence="evidence" :disabled="!!busy"/>
  <section v-if="evidence.report.scenario"><h4>{{!evidence.report.scenario.verified?'Unverified: no expectations supplied':evidence.report.scenario.passed?'Scenario expectations passed':'Scenario expectations failed'}}</h4><p>These are scenario assertions, not system contract claim verdicts. The trace uses the saved scenario; editor changes affect the next run.</p><p v-for="(a,i) in evidence.report.scenario.assertions" :key="i" :class="{error:!a.passed}">{{a.passed?'✓':'✗'}} {{a.path}} · {{a.message}}</p><details><summary>Saved scenario and final owner snapshots</summary><pre>{{JSON.stringify({scenario:evidence.scenario,final:evidence.report.scenario.final,workflows:evidence.report.scenario.workflows,messages:evidence.report.scenario.messages},null,2)}}</pre></details></section><div class="actions"><button :disabled="step===0" @click="step--">Previous</button><input aria-label="Trace step" type="range" min="0" :max="evidence.report.events.length-1" v-model.number="step"/><button :disabled="step>=evidence.report.events.length-1" @click="step++">Next</button><span aria-live="polite">{{step+1}} / {{evidence.report.events.length}} · {{current?.scenarioStep?'Scenario step '+current.scenarioStep+' · ':''}}{{current?.kind}}</span><button @click="download">Export execution</button></div>
  <SystemWorkflowTrace v-if="current?.workflow" :evidence="evidence" :event="current" :index="step"/><p v-if="focusedStep?.kind==='command'" class="scope">Explicit owner command: {{focusedStep.calls?.[0]?.command}}. This step has no graph transfers.</p><div class="task-strip"><button v-for="task in orderedTasks" :key="task.id" :class="{active:activeTask===task.id}" @click="focusOwner(task.id)"><strong>{{task.name}}</strong><small>{{task.slot}} · {{evidence.report.results.find(r=>r.taskId===task.id&&r.scenarioStep===current?.scenarioStep)?.operations}} operations</small></button></div>
  <div class="link-strip"><p v-for="link in visibleLinks" :key="link.id" :class="{active:current?.linkId===link.id}">{{name(link.source)}} / {{link.output}} → {{name(link.target)}} / {{link.input}}</p></div>
  <p v-if="current"><strong>{{name(current.taskId)}}</strong> · {{current.kind}}<template v-if="current.target"> → {{name(current.target)}}</template></p><pre v-if="!current?.message">{{JSON.stringify(current?.values,null,2)}}</pre>
 <section v-if="current?.message" class="message-evidence"><h4>Message journey · {{current.message.step.messageName||'Broker restart'}}</h4><ol class="journey"><li v-for="phase in messageJourney" :key="phase.kind" :class="{observed:phase.observed}">{{phase.observed?'✓':'○'}} {{phase.label}}</li></ol><p>{{current.message.step.status}} · Broker {{current.message.provider.id}} · Attempts {{current.message.step.beforeAttempts}} → {{current.message.step.afterAttempts}}</p><p v-if="current.message.step.status==='acknowledgement_lost'" class="scope">The recipient produced a receipt, but the sender has no acknowledgement. The message remains pending until an explicit retry.</p><p v-if="current.message.step.state">Recipient: {{current.message.step.state.status}} · Revision {{current.message.step.state.beforeRevision}} → {{current.message.step.state.afterRevision}}</p><details><summary>Frozen envelope, recipient receipt and transport snapshot</summary><pre>{{JSON.stringify(current.message,null,2)}}</pre></details></section>
  <section v-if="current?.state" class="state-evidence"><h4>State transition{{current.state.command?' · '+current.state.command:''}} · {{current.state.step.status}}{{current.state.step.replyLost?' · reply lost, no downstream transfer':''}}</h4><p>Revision {{current.state.step.beforeRevision}} → {{current.state.step.afterRevision}} · Provider {{current.state.provider.id}}</p><div class="task-strip"><section><h5>Before</h5><pre>{{JSON.stringify(current.state.step.before,null,2)}}</pre></section><section><h5>After</h5><pre>{{JSON.stringify(current.state.step.after,null,2)}}</pre></section></div><details><summary>Receipt and pending effect intents ({{current.state.instance.effects.length}})</summary><pre>{{JSON.stringify({receipt:current.state.step.receipt,effects:current.state.instance.effects},null,2)}}</pre><p>Intents are recorded atomically. A later explicit dispatch and delivery can process them when a message channel is bound. Each run starts fresh.</p></details></section><details><summary>Outputs and snapshot identity</summary><p>Design: {{evidence.designHash}}<br/>Inputs: {{evidence.inputHash}}<br/>Engine: {{evidence.report.engineVersion}} · Claims evaluated: {{evidence.report.claimsEvaluated}}</p><section v-for="result in evidence.report.results" :key="result.taskId+'-'+result.scenarioStep"><h4>{{name(result.taskId)}} · {{result.scenarioStep?'Step '+result.scenarioStep:''}} {{result.status}}</h4><pre>{{JSON.stringify(result.outputs,null,2)}}</pre><small>Bundle {{result.bundleHash}}</small></section></details>
  <p v-for="limit in evidence.report.limitations" :key="limit" class="scope">{{limit}}</p>
 </section>
</section>
</template>
<style scoped>
.journey{display:flex;flex-wrap:wrap;gap:8px;list-style:none;padding:0}.journey li{padding:9px;border:1px solid #cbdce3;border-radius:8px;color:#596b75}.journey .observed{background:#e4f6ec;border-color:#288563;color:#175a42}.execution-panel{min-width:0}.execution-panel button{border:1px solid #c8dbe3;border-radius:6px;background:#fff;padding:8px 12px;color:#285c52;cursor:pointer;font:inherit;font-size:12px}.execution-panel button:hover{background:#eaf6f1}.execution-panel button:disabled{opacity:.5;cursor:default}.execution-panel button:focus-visible{outline:2px solid #247e65;outline-offset:2px}.execution-panel p{font-size:13px;line-height:1.6}.scope{padding:12px;background:#fff8e5;border-radius:6px;color:#77622f}.actions,.history{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:12px 0}.actions input[type=range]{width:min(230px,100%)}.input-form{max-width:800px}.input-form fieldset.invalid{border-color:#c64242;box-shadow:0 0 0 1px #c64242}.input-form fieldset{border:1px solid #cbdce3;border-radius:8px;margin:14px 0;min-width:0;padding:15px}.input-form label{display:grid;gap:7px;margin:10px 0;font-size:12px}.input-form input,.input-form select,.input-form textarea{width:100%;min-width:0;box-sizing:border-box;border:1px solid #cbdce3;border-radius:5px;padding:9px}.task-strip{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(220px,100%),1fr));gap:12px}.task-strip button{display:grid;gap:8px;text-align:left;padding:15px!important;overflow-wrap:anywhere}.active{outline:2px solid #2e8a6b;background:#e6f8ed!important}.link-strip p{padding:10px;border:1px solid #d6e5dd;border-radius:6px;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;background:#f1f6f8;padding:14px;border-radius:6px;max-height:360px;overflow:auto}.trace-view details{overflow-wrap:anywhere}.error{color:#a13732;background:#fff0ef;padding:12px;border-radius:6px}.execution-panel small{overflow-wrap:anywhere}
</style>
